function signalExplanation(c){if(c.reason)return c.reason;if(c.primaryFailure&&state.snapshot?.health?.labels?.[c.primaryFailure])return 'Needs: '+state.snapshot.health.labels[c.primaryFailure]+(c.failureReasons?.length>1?` · ${c.failureReasons.length} checks not met`:'');return c.reason||({buy:'Passed correction, relative-value, stabilization and data-quality gates.',wait:'Price momentum or the wider set is weak. Wait for stabilization.',watch:'Verified evidence, but the full buying criteria are not met.',pending:'Pricing, printing identity, history or suitable peers still need verification.'}[c.signal]||'More verified evidence is needed.');}
