 return `<article class="card ${card.year<=2012&&/First Edition|Shadowless/.test(card.edition||'')?'vintage-special':''}" data-key="${esc(card.key)}" data-year="${card.year}" data-printing="${esc(card.printing||'Unconfirmed')}"><button class="art-button" data-detail="${esc(card.key)}" aria-label="View ${esc(card.name)} details">${image?`<img class="card-image" src="${esc(image)}" alt="${esc(card.name)} card artwork" width="160" height="224" loading="lazy" decoding="async">`:'<div class="card-placeholder" aria-label="Artwork unavailable">◈</div>'}</button><div class="card-main"><div class="rarity">${esc(card.rarity)}</div><h3><button data-detail="${esc(card.key)}">${esc(card.name)}</button></h3><div class="set">${esc(card.set)} · ${esc(card.number)} · ${card.year||'Year unverified'}</div><div class="printing-label">${esc(card.identityLabel||printingLabel(card))}</div><div class="market-price-label">Market Price</div><div class="price-line"><strong>${Number.isFinite(card.price)?esc(fmtMoney(card.price)):'Price Unavailable'}</strong>${Number.isFinite(card.change30)?`<span class="delta ${card.change30<0?'down':'up'}">${fmtDelta(card.change30)} 30D</span>`:''}</div><div class="price-date ${card.stale?'stale':''}">${esc(card.verifiedMatch?(card.stale?'STALE · ':'✓ ')+'TickerMint / TCGplayer · '+fmtDate(card.asOf):'Exact printing price not verified')}</div><div class="signal-row"><span class="signal ${card.signal}">${SIGNALS[card.signal]||SIGNALS.pending}</span><span class="score">SCORE <b>${card.score??'—'}</b></span></div><p class="card-reason">${esc(signalExplanation(card))}</p><p class="muted" style="font-size:9px;margin-top:8px">Data confidence: ${esc(card.confidenceLabel)} · ${card.confidence}/100</p><div class="card-actions"><button class="owned-button ${isOwned?'active':''}" data-own="${esc(card.key)}" aria-pressed="${isOwned}" aria-label="${review?'Review saved printing':isOwned?'Mark missing':'Mark owned'} ${esc(card.name)}">${review?'Review copy':isOwned?'✓ Owned':'＋ Own'}</button><button class="want-button ${want?'active':''}" data-want="${esc(card.key)}" aria-pressed="${want}" ${isOwned||review?'disabled':''}>${want?'★ Wanted':'☆ Want'}</button></div><button class="card-inspect" data-detail="${esc(card.key)}"><span>Details & collection</span><span>↗</span></button></div></article>`;
